class TokenBucket {
  /**
   * @param {object} options
   * @param {number} options.capacity - Kovadaki maksimum jeton kapasitesi.
   * @param {number} options.refillPerSecond - Saniyede yenilenen jeton miktarı.
   * @param {function(): number} [options.now] - Milisaniye döndüren zaman fonksiyonu (varsayılan Date.now).
   */
  constructor(options) {
    if (typeof options.capacity !== 'number' || options.capacity <= 0 || !isFinite(options.capacity)) {
      throw new RangeError('Capacity must be a positive finite number.');
    }
    if (typeof options.refillPerSecond !== 'number' || options.refillPerSecond < 0 || !isFinite(options.refillPerSecond)) {
      throw new RangeError('RefillPerSecond must be a non-negative finite number.');
    }

    this.capacity = options.capacity;
    this.refillPerSecond = options.refillPerSecond;
    this.now = options.now || Date.now;

    // Kova dolu başlar
    this.tokens = this.capacity;

    // Son dolumun gerçekleştiği zamanı izler (saat geriye gitmeyi engellemek için)
    this.lastRefillTime = this.now(); 
  }

  /**
   * Belirli bir zamana göre jeton miktarını günceller.
   * @private
   */
  refill() {
    const now = this.now();
    const timeElapsedMs = now - this.lastRefillTime;

    // Saat geriye gitmişse dolum yapılmaz.
    if (timeElapsedMs <= 0) {
      return;
    }

    // Geçen süreye göre yenilenmesi gereken jeton miktarı
    // (ms / 1000) * refillPerSecond
    const refillAmount = (timeElapsedMs / 1000) * this.refillPerSecond;

    // Yeni jeton miktarı, kapasiteyi geçmeyecek şekilde güncellenir
    this.tokens = Math.min(this.capacity, this.tokens + refillAmount);

    // Son dolum zamanını güncelliyoruz
    this.lastRefillTime = now;
  }

  /**
   * Mevcut jeton sayısını (kesirli) döndürür.
   * @returns {number}
   */
  available() {
    this.refill(); // Güncel durumu hesapla
    return this.tokens;
  }

  /**
   * Belirtilen miktarda jeton almayı dener.
   * @param {number} [n=1] - Alınacak jeton miktarı.
   * @returns {boolean} - Başarılıysa true, değilse false.
   */
  tryTake(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !isFinite(n)) {
      throw new RangeError('n must be a positive finite number.');
    }

    // Önce yenilemeyi yap, mevcut jeton sayısını al
    this.refill();

    if (this.tokens >= n) {
      this.tokens -= n;
      return true;
    } else {
      // Yetersiz jeton varsa hiçbir şey düşülmez
      return false;
    }
  }

  /**
   * n jetonun kullanılabilir olmasına gereken süreyi milisaniye cinsinden hesaplar.
   * @param {number} [n=1] - Gereken jeton miktarı.
   * @returns {number} - Gerekli süre (ms) veya Infinity.
   */
  msUntil(n = 1) {
    if (typeof n !== 'number' || n <= 0 || !isFinite(n)) {
      throw new RangeError('n must be a positive finite number.');
    }

    this.refill();

    if (this.tokens >= n) {
      return 0; // Yeterli jeton var
    }

    if (this.refillPerSecond <= 0 || n > this.capacity) {
      return Infinity; // Yenilenme yok veya istek kapasiteyi aşıyor
    }

    // İhtiyaç duyulan ek jeton miktarı
    const neededTokens = n - this.tokens;

    // Gerekli süre (ms) = (İhtiyaç duyulan jeton / Yenilenme hızı) * 1000
    const requiredTimeMs = (neededTokens / this.refillPerSecond) * 1000;

    // Yukarı yuvarlanmış tam sayı olarak döndürülmeli
    return Math.ceil(requiredTimeMs);
  }
}

module.exports = { TokenBucket };

args.command:
node -e "const { TokenBucket } = require('./kova.js');

// --- Test Case 1: Initialization and Full Start ---
try {
  const nowMock = () => 1000;
  const tb1 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMock });
  console.log('Test 1 Passed: Initial tokens:', tb1.available()); // Should be 5
} catch (e) { console.error('Test 1 Failed:', e.message); }

// --- Test Case 2: Successful Take ---
try {
  const nowMock = () => 1000;
  const tb2 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMock });
  const took = tb2.tryTake(2);
  console.log('Test 2 Passed: TryTake 2 successful:', took); // Should be true
  console.log('Test 2 Tokens After Take:', tb2.available()); // Should be 3
} catch (e) { console.error('Test 2 Failed:', e.message); }

// --- Test Case 3: Unsuccessful Take ---
try {
  const nowMock = () => 1000;
  const tb3 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMock });
  const took = tb3.tryTake(6);
  console.log('Test 3 Passed: TryTake 6 unsuccessful:', !took); // Should be true
  console.log('Test 3 Tokens After Failed Take:', tb3.available()); // Should be 5 (no change)
} catch (e) { console.error('Test 3 Failed:', e.message); }

// --- Test Case 4: Refill Over Time (1 second later) ---
try {
  const nowMock = () => 2000; // 1000ms elapsed
  const tb4 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMock }); // Starts at 5
  // Initial state is 5, refill logic applies change to lastRefillTime=1000
  // Refill calculation for 1000ms elapsed: (1000/1000) * 2 = 2 jeton eklenmeli, max 5.
  const available = tb4.available(); 
  console.log('Test 4 Passed: Refill amount (should be 5):', available >= 5);

  // Test partial refill (e.g., 500ms elapsed)
  const nowMockPartial = () => 1500; // 500ms elapsed
  const tb5 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMockPartial });
  // Initial 5. 500ms elapsed -> (0.5) * 2 = 1 jeton eklenmeli. Max 5.
  // Since it starts full, it stays 5, but the logic should handle it correctly.
  // Let's test with an empty start for better refill validation:
  const tb6 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMockPartial }); // Start 5
  tb6.tryTake(5); // Tokens = 0 at t=1500
  // Now simulate refill from t=1500 to t=2000 (500ms later)
  const tb7 = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: () => 2000 });
  tb7.tryTake(5); // Tokens = 0
  tb7.available(); // Refill from 1500 to 2000 (500ms). (0.5 * 2) = 1 jeton.
  console.log('Test 4.1 Passed: Partial Refill (1 jeton):', Math.abs(tb7.available() - 1) < 0.001);
} catch (e) { console.error('Test 4 Failed:', e.message); }

// --- Test Case 5: msUntil ---
try {
  const nowMock = () => 1000;
  const tb5_until = new TokenBucket({ capacity: 5, refillPerSecond: 2, now: nowMock }); // Start 5
  console.log('Test 5.1 Passed: msUntil 1 (should be 0):', tb5_until.msUntil(1) === 0);

  tb5_until.tryTake(5); // Tokens = 0
  // Need 1 jeton. Refill rate 2/s. Need 0.5s -> 500ms
  console.log('Test 5.2 Passed: msUntil 1 (should be 500):', tb5_until.msUntil(1) === 500);
  // Need 3 jeton. Need 1.5s -> 1500ms
  console.log('Test 5.3 Passed: msUntil 3 (should be 1500):', tb5_until.msUntil(3) === 1500);
} catch (e) { console.error('Test 5 Failed:', e.message); }

// --- Test Case 6: Error Handling ---
try {
  new TokenBucket({ capacity: 0, refillPerSecond: 1 });
  console.log('Test 6.1 Failed: Capacity check missed.');
} catch (e) { console.log('Test 6.1 Passed: Capacity Error caught.'); }

try {
  new TokenBucket({ capacity: 5, refillPerSecond: -1 });
  console.log('Test 6.2 Failed: RefillPerSecond check missed.');
} catch (e) { console.log('Test 6.2 Passed: RefillPerSecond Error caught.'); }

try {
  new TokenBucket({ capacity: 5, refillPerSecond: 1 });
  try {
    tb6.tryTake(0);
  } catch (e) { console.log('Test 6.3 Passed: TryTake n=0 Error caught.'); }
} catch (e) { console.error('Test 6 Failed:', e.message); }

console.log('\n--- Tüm Temel Testler Tamamlandı ---');
"
